"use strict";(globalThis.webpackChunk_platform_site||=[]).push([[7152],{81910(e){e.exports=JSON.parse('{"tag":{"label":"platform","permalink":"/documentation-system/tags/platform","allTagsPath":"/documentation-system/tags","count":18,"items":[{"id":"platform/extending/add-content-backend","title":"Add a content backend","description":"Step-by-step recipe for a new ContentBackend (for example a server-side backend or a different git host): the operations to implement, the shared pipelines to reuse, the contract suite that proves substitutability, and where the editor and site composition roots pick it.","permalink":"/documentation-system/platform/extending/add-content-backend"},{"id":"platform/extending/add-deploy-target","title":"Add a deploy target","description":"Recipe for hosting the site somewhere other than GitHub Pages (another static host, Docker, a Node process): what site:build produces, which config fields fix the URLs, what in-place editing needs from the host and how the Phase 2 server is mounted, and the workflow to add without touching deploy-pages.yml.","permalink":"/documentation-system/platform/extending/add-deploy-target"},{"id":"platform/extending/add-service-module","title":"Add a new service module","description":"General recipe for a brand-new workspace under services/ or packages/ (for example the Phase 2 gate or the Hono shell): package layout, tsconfig and Vitest wiring, the ESLint boundary element to declare, and which scripts and workflows must know about it.","permalink":"/documentation-system/platform/extending/add-service-module"},{"id":"platform/extending/add-site-plugin-or-viewer","title":"Add a site plugin or viewer component","description":"Recipe for a new MDX component (a viewer for another asset format, or any block the editor should insert) and for a Docusaurus plugin: where the rendering core lives, how the site registers it globally, how components.json exposes it to the editor, and which lint elements are involved.","permalink":"/documentation-system/platform/extending/add-site-plugin-or-viewer"},{"id":"platform/extending/add-auth-provider","title":"Add an auth provider","description":"Step-by-step recipe for a new AuthProvider (for example the Phase 2 password provider): the interface and credentials union to extend, the contract suite to pass, where the site\'s in-place editing composition root selects it, the sign-in panel to register and which config field switches it on.","permalink":"/documentation-system/platform/extending/add-auth-provider"},{"id":"platform/agent-skill","title":"Agent skill","description":"Explains the docs-platform agent skill (the only platform agent skill), its user-level registry that maps a code repository to its docs bundle, the navigation walk it prescribes and its relationship to the ray-okf-core format skill; open it when setting up an agent to work on this documentation or when a repo is \\"not registered\\".","permalink":"/documentation-system/platform/agent-skill"},{"id":"platform/architecture","title":"Architecture","description":"Explains which packages and services make up the platform, which may import which, and the exact sequence of calls behind a login, a save, a version publish and a 3D asset fetch; read this before touching more than one workspace.","permalink":"/documentation-system/platform/architecture"},{"id":"platform/auth","title":"Auth service","description":"Explains how the GitHub token provider decides who may edit (repository push permission), how the mock provider serves tests, and where sessions live in the browser; open it when a login fails or when you need the provider behaviour a new AuthProvider has to match.","permalink":"/documentation-system/platform/auth"},{"id":"platform/comments","title":"Comments","description":"Explains comments on the text of Latest docs pages (highlights for every reader, hover and thread cards, the Comments panel with Open, Unattached and Resolved, replies, resolve, reopen and delete, comments inside tabs), where they are stored (one JSON file per page under site/comments, committed to main), how readers get them without the GitHub API, how a comment finds its text again, and how it is tested; open it when changing comments or when a comment shows in the wrong place.","permalink":"/documentation-system/platform/comments"},{"id":"platform/content","title":"Content service","description":"Describes the three ContentBackend implementations (local folder, GitHub-in-browser, HTTP bridge), the shared write and publish pipelines, the LFS-aware asset fetch and the Orama search; open it when a save, publish or asset load misbehaves or when you are writing a new backend.","permalink":"/documentation-system/platform/content"},{"id":"platform/contracts","title":"Contracts","description":"Lists every interface, type and error code in @platform/contracts and the three contract test suites that any new auth provider, content backend or comment store must pass; open it when you need the exact signature a service has to implement.","permalink":"/documentation-system/platform/contracts"},{"id":"platform/editor","title":"Editor service","description":"Describes in-place editing of the docs pages (Edit button, lazily loaded editor library, sign-in, Visual and Raw modes, page settings, page actions, saving to GitHub or to disk on the dev server, pending previews), how the editor library is composed by the site, how Markdown is imported and written back, how the page look and the isolated stylesheet work, and how it is tested; open it when changing editing behaviour or debugging a save.","permalink":"/documentation-system/platform/editor"},{"id":"platform/okf-core","title":"OKF Core package","description":"Describes the zero-dependency generator and validator that turns page frontmatter into index blocks, manifest.json, code maps and log entries, including its public API, validator rules and the browser/Node split; open it when a validation report or a stale-content error needs explaining.","permalink":"/documentation-system/platform/okf-core"},{"id":"platform/decisions","title":"Platform decisions","description":"Summarises the twenty design decisions recorded in section 7 of the specification (viewers package, TS contracts over OpenAPI, in-memory okf-core, composition roots, sample repo layout, frozen 1.0.0, code maps, two search indexes, and more) with the reason for each, plus later decisions such as Plate replacing MDXEditor, in-place editing replacing the standalone editor app and how comments are stored and shown; read it before reopening any of them.","permalink":"/documentation-system/platform/decisions"},{"id":"platform/roadmap","title":"Roadmap","description":"Lists what Phase 2 adds (password provider from GitHub secrets, server-side content service behind a Hono shell, a gate for private viewing, Docker or Node deployment, the push-triggered documentation updater) and the editor\'s known minor issues; open it to see what is planned versus shipped before proposing a change.","permalink":"/documentation-system/platform/roadmap"},{"id":"platform/site","title":"Site","description":"Describes the Docusaurus site: how docusaurus.config.js derives everything from platform.config.js, which files are excluded from rendering, what the prebuild writes to static/platform, how the in-place editing plugin and theme wrappers hook in, and how versions and the composition root work; open it when the rendered site differs from the docs folder or when wiring a new site feature.","permalink":"/documentation-system/platform/site"},{"id":"platform/viewers","title":"Viewers package","description":"Explains the two React 3D rendering cores (glTF/GLB through model-viewer, FBX through three.js), why they live in their own package, and how the site wraps them with BrowserOnly and asset resolution; open it when a model does not render or when adding a new viewer.","permalink":"/documentation-system/platform/viewers"},{"id":"platform/workflows","title":"Workflows and scripts","description":"Lists the GitHub Actions workflows (validate on every push, deploy Pages on main) and the root npm scripts with what each one runs; open it when CI fails, when reproducing CI locally, or when adding a build step or deploy target.","permalink":"/documentation-system/platform/workflows"}],"unlisted":false}}')}}]);